        return Color('named', s)
    if ',' in s:
        parts = s.split(',')
        ok = len(parts)==3 and all(p.isdigit() and 0 <= int(p) <= 255 for p in parts)
        if ok:
            return Color('rgb', tuple(int(p) for p in parts))
        die255(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{s}'")
    if s.isdigit():
        n = int(s)
        if 0 <= n <= 255:
            return Color('ansi256', n)
        die255(f"unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{s}'")
    die255(f"unexpected color value: unrecognized color name '{s}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white")

def apply_color_spec(styles, spec):
    if ':' in spec:
        face, rest = spec.split(':',1)
        attrs = rest.split(':')
    else:
        face, attrs = spec, []
    if face not in styles:
        die255(f"unexpected face name: got '{face}', {FACE_ERR}")
    st = styles[face]
    i=0
    while i < len(attrs):
        a = attrs[i]
        if a == 'foreground' or a == 'background':
            if i+1 >= len(attrs):
                die255(f"unexpected attribute name: got '', {ATTR_ERR}")
            c = parse_color(attrs[i+1])
            if a == 'foreground': st.fg = c
            else: st.bg = c
            i += 2
            continue
        if a == 'none': st.clear()
        elif a == 'bold': st.bold=True
        elif a == 'nobold': st.bold=False
        elif a == 'italic': st.italic=True
        elif a == 'noitalic': st.italic=False
        elif a == 'dimmed': st.dimmed=True
        elif a == 'nodimmed': st.dimmed=False
        elif a == 'intense': st.intense=True
        elif a == 'nointense': st.intense=False
        elif a == 'underline': st.underline=True
        elif a == 'nounderline': st.underline=False
        else:
            die255(f"unexpected attribute name: got '{a}', {ATTR_ERR}")
        i += 1

def parse_args(argv):
    styles = default_styles()
    line_numbers = None
    i=0
    while i < len(argv):
        a = argv[i]
        if a == '-h':
            sys.stdout.write(SHORT_HELP); sys.exit(0)
        if a == '--help':
            sys.stdout.write(LONG_HELP); sys.exit(0)
        if a == '-V' or a == '--version':
            sys.stderr.write(f"diffr {VERSION}\n"); sys.exit(0)
        if a == '--colors':
            if i+1 >= len(argv):
                sys.stderr.write("option requires an argument: '--colors'\n"); sys.exit(2)
            apply_color_spec(styles, argv[i+1]); i += 2; continue
        if a == '--line-numbers':
            line_numbers = 'compact'
            if i+1 < len(argv) and not argv[i+1].startswith('-'):
                val = argv[i+1]
                if val not in ('aligned','compact','fixed'):
                    sys.stderr.write(f"unexpected line number style: got '{val}', expected aligned|compact|fixed\n"); sys.exit(255)
                line_numbers = val
                i += 2
            else:
                i += 1
            continue
        sys.stderr.write(f"bad argument: '{a}'\n")
        sys.stderr.write(SHORT_HELP)
        sys.exit(2)
    return styles, line_numbers

def paint(style, data):
    return ESC0 + style.seq() + data + ESC0

def is_word_byte(c):
    return (48 <= c <= 57) or (65 <= c <= 90) or (97 <= c <= 122) or c == 95 or c >= 128

def is_ws_byte(c):
    return c in (9,10,11,12,13,32)

def tokenize_line(body, line_idx):
    toks=[]
    i=0; n=len(body)
    while i<n:
        c = body[i]
        j=i+1
        if is_word_byte(c):
            while j<n and is_word_byte(body[j]): j+=1
        elif is_ws_byte(c):
            while j<n and is_ws_byte(body[j]): j+=1
        # punctuation is one byte
        toks.append({'val': body[i:j], 'line': line_idx, 'start': i, 'end': j, 'lb': False})
        i=j
    return toks

def leading_ws(rest):
    i=0
    while i < len(rest) and rest[i] in (32,9):
        i += 1
    return rest[:i], rest[i:]

@dataclass
class ChangeLine:
    sign: int
    rest: bytes
    nl: bytes
    oldno: object
    newno: object
    leading: bytes = b''
    body: bytes = b''
    segs: object = None
    refined_lb: bool = False

HUNK_RE = re.compile(br'^@@ -([0-9]+)(?:,([0-9]+))? \+([0-9]+)(?:,([0-9]+))? @@')

def split_input(data):
    if not data: return []
    parts = data.split(b'\n')
    out=[]
    for idx,p in enumerate(parts):
        if idx == len(parts)-1:
            if p: out.append((p,b''))
        else:
            out.append((p,b'\n'))
    return out

def hunk_width(old_start, old_count, new_start, new_count):
    old_end = old_start + max(old_count,1) - 1
    new_end = new_start + max(new_count,1) - 1
    return max(len(str(old_end)), len(str(new_end)))

def num_prefix(kind, oldno, newno, width):
    if kind == 'remove':
        a = str(oldno); b = ''
    elif kind == 'add':
        a = ''; b = str(newno)
    else:
        if oldno == newno:
            a = ''
        else:
            a = str(oldno)
        b = str(newno)
    return (a.rjust(width) + ' ' + b.rjust(width)).encode()

def build_tokens(lines):
    toks=[]
    for i,cl in enumerate(lines):
        toks.extend(tokenize_line(cl.body, i))
        if i != len(lines)-1:
            toks.append({'val': LINE, 'line': i, 'start': len(cl.body), 'end': len(cl.body), 'lb': True})
    return toks

def annotate_side(lines, flags):
    # lines already have bodies; flags parallels token array from build_tokens
    for cl in lines:
        cl.segs=[]; cl.refined_lb=False
    toks = build_tokens(lines)
    for tok, ref in zip(toks, flags):
        li = tok['line']
        cl = lines[li]
        if tok['lb']:
            if ref:
                add_seg(cl, 'refine', b'', is_lb=True)
                cl.refined_lb = True
            continue
        text = tok['val']
        if ref:
            if text and all(is_ws_byte(x) for x in text) and tok['end'] == len(cl.body):
                sty = 'bad'
            else:
                sty = 'refine'
        else:
            sty = 'base'
        add_seg(cl, sty, text)
    for cl in lines:
        if cl.segs:
            sty, txt = cl.segs[-1]
            if sty in ('refine','bad') and txt and not cl.refined_lb:
                cl.segs.append(('base', b''))
        elif cl.body == b'':
            # no body: nothing after prefix/sign
            pass

def add_seg(cl, sty, text, is_lb=False):
    if cl.segs and cl.segs[-1][0] == sty:
        if text:
            oldsty, oldtxt = cl.segs[-1]
            cl.segs[-1] = (oldsty, oldtxt + text)
        return
    # Empty linebreak refinements are meaningful after a base segment.
    if text or sty == 'refine':
        cl.segs.append((sty, text))

def compute_block(lines):
    removed=[cl for cl in lines if cl.sign == ord('-')]
    added=[cl for cl in lines if cl.sign == ord('+')]
    for cl in lines:
        cl.leading, cl.body = leading_ws(cl.rest)
    rtoks=build_tokens(removed); atoks=build_tokens(added)
    rvals=[t['val'] for t in rtoks]; avals=[t['val'] for t in atoks]
    rflags=[False]*len(rtoks); aflags=[False]*len(atoks)
    sm=SequenceMatcher(None, rvals, avals, autojunk=False)
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag != 'equal':
            for k in range(i1,i2): rflags[k]=True
            for k in range(j1,j2): aflags[k]=True
    annotate_side(removed, rflags)
    annotate_side(added, aflags)

def render_change_line(cl, styles, ln_style, width):
    base_name = 'removed' if cl.sign == ord('-') else 'added'
    ref_name = 'refine-removed' if cl.sign == ord('-') else 'refine-added'
    base = styles[base_name]; refine = styles[ref_name]
    out=b''
    if ln_style:
        kind = 'remove' if cl.sign == ord('-') else 'add'
        out += paint(base, num_prefix(kind, cl.oldno, cl.newno, width))
        if ln_style == 'aligned': out += b'\t'
    out += paint(base, bytes([cl.sign]) + cl.leading)
    for sty, text in (cl.segs or []):
        if sty == 'base': out += paint(base, text)
        elif sty == 'bad': out += paint(BAD_WS, text)
        else: out += paint(refine, text)
    out += cl.nl
    return out

def render_context(content, nl, oldno, newno, ln_style, width):
    if ln_style:
        pre = num_prefix('context', oldno, newno, width)
        if ln_style == 'aligned': pre += b'\t'
        return pre + paint(EMPTY, content) + nl
    return paint(EMPTY, content) + nl

def process(data, styles, ln_style):
    records = split_input(data)
    out=[]
    in_hunk=False
    old_line=0; new_line=0; width=1
    block=[]
    def flush():
        nonlocal block
        if block:
            compute_block(block)
            for cl in block:
                out.append(render_change_line(cl, styles, ln_style, width))
            block=[]
    for content,nl in records:
        m = HUNK_RE.match(content)
        if m:
            flush()
            out.append(paint(EMPTY, content) + nl)
            old_line = int(m.group(1)); new_line = int(m.group(3))
            old_count = int(m.group(2) or b'1'); new_count = int(m.group(4) or b'1')
            width = hunk_width(old_line, old_count, new_line, new_count)
            in_hunk=True
            continue
        if in_hunk and content.startswith((b'-',b'+')):
            if content[0] == ord('-'):
                block.append(ChangeLine(ord('-'), content[1:], nl, old_line, None)); old_line += 1
            else:
                block.append(ChangeLine(ord('+'), content[1:], nl, None, new_line)); new_line += 1
            continue
        flush()
        if in_hunk and content.startswith(b' '):
            out.append(render_context(content, nl, old_line, new_line, ln_style, width))
            old_line += 1; new_line += 1
        else:
            out.append(paint(EMPTY, content) + nl)
    flush()
    return b''.join(out)

def main():
    styles, ln_style = parse_args(sys.argv[1:])
    data = sys.stdin.buffer.read()
    sys.stdout.buffer.write(process(data, styles, ln_style))

if __name__ == '__main__':
    main()
